WORKLOADS = [
    {"name": "core-banking", "vendor_lockin_risk": "high", "needs_best_of_breed": False, "team_platform_skills": 2},
    {"name": "marketing-site", "vendor_lockin_risk": "low", "needs_best_of_breed": False, "team_platform_skills": 1},
    {"name": "ml-training", "vendor_lockin_risk": "low", "needs_best_of_breed": True, "team_platform_skills": 2},
    {"name": "internal-crm", "vendor_lockin_risk": "medium", "needs_best_of_breed": False, "team_platform_skills": 3},
]

def score_workload(w):
    score = 0
    if w["vendor_lockin_risk"] == "high":
        score += 2
    if w["needs_best_of_breed"] is True:
        score += 2
    if w["team_platform_skills"] >= 2:
        score += 1
    return score

def classify(score):
    return "MULTI_CLOUD" if score >= 3 else "SINGLE_CLOUD"

multi_count = 0
for w in WORKLOADS:
    s = score_workload(w)
    label = classify(s)
    if label == "MULTI_CLOUD":
        multi_count += 1
    print(f"{w['name']}: score={s} -> {label}")

print(f"MULTI_CLOUD workloads: {multi_count}/{len(WORKLOADS)}")
